package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FilteringParserDelegate#nextToken
 */
public class FilteringParserDelegate_nextToken_TriageGen1Test {

    private JsonParser mockDelegate;
    private TokenFilter mockFilter;
    private TokenFilterContext mockHeadContext;

    // Since FilteringParserDelegate is a class with protected members and a specific constructor,
    // we use a subclass or spy to inject the necessary state for testing complex logic.
    private TestFilteringParserDelegate delegate;

    // Subclass to allow setting protected fields for white-box testing
    private static class TestFilteringParserDelegate extends FilteringParserDelegate {
        public TokenFilterContext _headContext;
        public TokenFilterContext _exposedContext;
        public boolean _includePath;
        public boolean _includeImmediateParent;
        public boolean _allowMultipleMatches;
        public TokenFilter _itemFilter;

        public TestFilteringParserDelegate(JsonParser p, TokenFilter f, boolean includePath, boolean allowMultipleMatches) {
            super(p, f, includePath, allowMultipleMatches);
        }

        @Override
        protected JsonToken _nextToken2() throws IOException {
            return JsonToken.NOT_AVAILABLE;
        }

        @Override
        protected JsonToken _nextTokenWithBuffering(TokenFilterContext buffRoot) throws IOException {
            return JsonToken.START_OBJECT;
        }

        // Helper to inject state into protected fields via reflection or direct access in test subclass
        public void setInternalState(TokenFilterContext head, TokenFilterContext exposed, boolean includePath, boolean includeImmediateParent, boolean allowMultipleMatches, TokenFilter itemFilter) {
            this._headContext = head;
            this._exposedContext = exposed;
            this._includePath = includePath;
            this._includeImmediateParent = includeImmediateParent;
            this._allowMultipleMatches = allowMultipleMatches;
            this._itemFilter = itemFilter;
        }

        // Overriding to access protected fields for the test
        @Override
        public JsonToken nextToken() throws IOException {
            // We must use the actual logic but we need to be able to manipulate the internal fields 
            // which are not accessible in the base class. In a real Jackson test, 
            // these are often accessed via reflection.
            return super.nextToken();
        }
    }

    @Before
    public void setUp() throws IOException {
        mockDelegate = mock(JsonParser.class);
        mockFilter = mock(TokenFilter.class);
        mockHeadContext = mock(TokenFilterContext.class);

        // Initializing the delegate
        delegate = new TestFilteringParserDelegate(mockDelegate, mockFilter, false, true);

        // Use reflection to set the private/protected fields that the method relies on
        setField(delegate, "_headContext", mockHeadContext);
        setField(delegate, "_exposedContext", null);
        setField(delegate, "_includePath", false);
        setField(delegate, "_includeImmediateParent", false);
        setField(delegate, "_allowMultipleMatches", true);
        setField(delegate, "_itemFilter", null);
    }

    @Test
    public void testNextToken_NullDelegateReturnsNull() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(null);
        assertNull(delegate.nextToken());
    }

    @Test
    public void testNextToken_AllowMultipleMatchesFalse_StructEndReturnsNull() throws IOException {
        setField(delegate, "_allowMultipleMatches", false);
        setField(delegate, "_includePath", false);

        JsonToken endToken = JsonToken.END_OBJECT;
        setField(delegate, "_currToken", endToken);
        when(mockHeadContext.isStartHandled()).thenReturn(true);

        // Simulate end of stream logic in the first if block
        // The code does: if (_currToken.isStructEnd()) ... return (_currToken = null)
        // Since we can't mock JsonToken.isStructEnd() (it's an enum), 
        // we rely on the fact that END_OBJECT is a struct end.

        // Note: To trigger the first block, _exposedContext must be null
        assertNull(delegate.nextToken());
    }

    @Test
    public void testNextToken_ExposedContextBufferedTokens() throws IOException {
        TokenFilterContext mockExposed = mock(TokenFilterContext.class);
        setField(delegate, "_exposedContext", mockExposed);
        setField(delegate, "_headContext", mockHeadContext);

        when(mockExposed.nextTokenToRead()).thenReturn(JsonToken.FIELD_NAME);

        assertEquals(JsonToken.FIELD_NAME, delegate.nextToken());
        verify(mockExposed).nextTokenToRead();
    }

    @Test
    public void testNextToken_StartArray_IncludeAll() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        setField(delegate, "_itemFilter", TokenFilter.INCLUDE_ALL);

        // In the code, if f == INCLUDE_ALL, it creates child context and returns
        // We need to mock the headContext behavior
        when(mockHeadContext.createChildArrayContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mockHeadContext);

        assertEquals(JsonToken.START_ARRAY, delegate.nextToken());
    }

    @Test
    public void testNextToken_StartArray_SkipChildren() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        setField(delegate, "_itemFilter", null); // f is null

        assertEquals(JsonToken.NOT_AVAILABLE, delegate.nextToken());
        verify(mockDelegate).skipChildren();
    }

    @Test
    public void testNextToken_StartObject_IncludeAll() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_OBJECT);
        setField(delegate, "_itemFilter", TokenFilter.INCLUDE_ALL);
        when(mockHeadContext.createChildObjectContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mockHeadContext);

        assertEquals(JsonToken.START_OBJECT, delegate.nextToken());
    }

    @Test
    public void testNextToken_EndArray_ReturnsToken() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.END_ARRAY);
        when(mockHeadContext.isStartHandled()).thenReturn(true);
        when(mockHeadContext.getFilter()).thenReturn(null);
        when(mockHeadContext.getParent()).thenReturn(mockHeadContext);

        assertEquals(JsonToken.END_ARRAY, delegate.nextToken());
    }

    @Test
    public void testNextToken_FieldName_IncludeAll() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(mockDelegate.getCurrentName()).thenReturn("testField");
        when(mockHeadContext.setFieldName("testField")).thenReturn(TokenFilter.INCLUDE_ALL);

        // If !includePath and includeImmediateParent is true
        setField(delegate, "_includePath", false);
        setField(delegate, "_includeImmediateParent", true);
        when(mockHeadContext.isStartHandled()).thenReturn(false);
        when(mockHeadContext.nextTokenToRead()).thenReturn(JsonToken.START_OBJECT);

        assertEquals(JsonToken.START_OBJECT, delegate.nextToken());
    }

    @Test
    public void testNextToken_ScalarValue_IncludeAll() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);
        setField(delegate, "_itemFilter", TokenFilter.INCLUDE_ALL);

        assertEquals(JsonToken.VALUE_STRING, delegate.nextToken());
    }

    @Test
    public void testNextToken_ScalarValue_CheckValue() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_NUMBER_INT);
        setField(delegate, "_itemFilter", mock(TokenFilter.class));
        when(mockHeadContext.checkValue(any())).thenReturn(TokenFilter.INCLUDE_ALL);

        assertEquals(JsonToken.VALUE_NUMBER_INT, delegate.nextToken());
    }

    @Test
    public void testNextToken_FieldNotIncluded() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(mockDelegate.getCurrentName()).thenReturn("hidden");
        when(mockHeadContext.setFieldName("hidden")).thenReturn(null);

        // When f is null, it calls skipChildren
        assertEquals(JsonToken.NOT_AVAILABLE, delegate.nextToken());
        verify(mockDelegate).skipChildren();
    }

    // Helper to set private fields for testing
    private void setField(Object obj, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = obj.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(obj, value);
        } catch (Exception e) {
            try {
                // Try superclass if not found in subclass
                java.lang.reflect.Field field = obj.getClass().getSuperclass().getDeclaredField(fieldName);
                field.setAccessible(true);
                field.set(obj, value);
            } catch (Exception ex) {
                throw new RuntimeException(ex);
            }
        }
    }
}
